/**
 * fyd/ts-tokens: DTCG -> typed TS token map.
 *
 * For tests and non-DOM consumers (contrast gate, planner previews).
 * Frozen object mirroring token paths with literal types. Keys sorted
 * alphabetically at every level so rebuilds are byte-identical.
 */
const HEADER = `/**
 * DO NOT EDIT. Generated by fyd-product-lane/builder/tokens/build.cjs
 * from DTCG 2025.10 sources.
 */`;

function setPath(root, path, value) {
  let node = root;
  for (let i = 0; i < path.length - 1; i++) {
    const key = path[i];
    if (typeof node[key] !== "object" || node[key] === null) node[key] = {};
    node = node[key];
  }
  node[path[path.length - 1]] = value;
}

function sortDeep(value) {
  if (Array.isArray(value)) return value.map(sortDeep);
  if (value !== null && typeof value === "object") {
    const out = {};
    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
    return out;
  }
  return value;
}

function renderTs(value, indent) {
  if (value !== null && typeof value === "object") {
    const entries = Object.keys(value).map(
      (k) => `${indent}  ${JSON.stringify(k)}: ${renderTs(value[k], indent + "  ")}`,
    );
    return `{\n${entries.join(",\n")}\n${indent}}`;
  }
  return JSON.stringify(value);
}

export function registerTsTokensFormat(StyleDictionary) {
  StyleDictionary.registerFormat({
    name: "fyd/ts-tokens",
    format: ({ dictionary, options }) => {
      const theme = options.theme ?? "unknown";
      const exportName = options.exportName ?? `${theme}Tokens`;
      const typeName = options.typeName ?? `${theme}Tokens`;
      const root = {};
      for (const token of dictionary.allTokens) {
        const p = token.path;
        if (p[0] === "font" && (p[1] === "display" || p[1] === "body") && p[2] !== undefined && p[2] !== theme) {
          continue; // the other theme's font stack is not this theme's binding
        }
        setPath(root, p, token.$value ?? token.value);
      }
      const sorted = sortDeep(root);
      return (
        `${HEADER}\nexport const ${exportName} = ${renderTs(sorted, "")} as const;\n\n` +
        `export type ${typeName} = typeof ${exportName};\n`
      );
    },
  });
}
